DROP TABLE IF EXISTS `logistics_orders`;
CREATE TABLE `logistics_orders`(logistics_orders_id int(11) NOT NULL AUTO_INCREMENT COMMENT '物流订单ID',
`order_number` varchar(64) comment '订单编号',
`user_information` int(11) DEFAULT 0 comment '用户信息',
`product_name` varchar(64) comment '商品名称',
`order_date` date comment '订单日期',
`purchase_quantity` int(11) DEFAULT 0 comment '购买数量',
