cart_img_1 = CONCAT('/api',cart_img_1),
cart_img_2 = CONCAT('/api',cart_img_2),
cart_img_3 = CONCAT('/api',cart_img_3),
cart_img_4 = CONCAT('/api',cart_img_4),
cart_img_5 = CONCAT('/api',cart_img_5);
